<div id="page-content" class="page-wrapper clearfix"><div class="card"><div class="page-title clearfix"><h1><?php echo esc($checklist->name); ?> <small class="text-muted">v<?php echo (int)$checklist->version; ?></small></h1><div class="title-button-group"><a class="btn btn-default" href="<?php echo get_uri('engenharia/checklists/manage/' . $checklist->id); ?>"><?php echo app_lang('back'); ?></a></div></div><div class="card-body"><?php foreach($groups as $group){ ?><div class="card mb15"><div class="card-header"><h5 class="mb0"><?php echo esc($group->title); ?></h5></div><div class="card-body"><?php foreach($items as $item){if((int)$item->group_id !== (int)$group->id)continue; ?><div class="border-bottom pb10 mb10"><strong><?php echo esc($item->code); ?> - <?php echo esc($item->title); ?></strong><p class="mb5"><?php echo nl2br(esc($item->question)); ?></p><small class="text-muted"><?php echo esc($item->norm_reference); ?></small></div><?php } ?></div></div><?php } ?></div></div></div>
